// The app's logic and data. No page code here: ui.js uses these functions and tests/app.test.js tests them.

const STORAGE_KEY = "foundry-app";

/** Read saved data, or return the fallback when nothing is saved (or storage is unavailable). */
function loadData(fallback) {
  try {
    const raw = globalThis.localStorage && globalThis.localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

/** Save data so it is still there next time the app is opened. */
function saveData(data) {
  try {
    if (globalThis.localStorage) globalThis.localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch {
    // storage full or blocked: the app keeps working, it just won't remember
  }
}

function addCard(state, front, back) {
  const f = String(front == null ? "" : front).trim();
  const b = String(back == null ? "" : back).trim();
  if (!f || !b) {
    return { ok: false, state: state, message: "Please fill in both the front and the back." };
  }
  const cards = state.cards.concat([{ front: f, back: b }]);
  return {
    ok: true,
    state: { cards: cards, index: cards.length - 1, showingFront: true },
    message: "",
  };
}

function flipCard(state) {
  if (!state.cards.length) return state;
  return { cards: state.cards, index: state.index, showingFront: !state.showingFront };
}

function shuffleDeck(state, randomFn) {
  const rand = typeof randomFn === "function" ? randomFn : Math.random;
  const cards = state.cards.slice();
  for (let i = cards.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const t = cards[i];
    cards[i] = cards[j];
    cards[j] = t;
  }
  return { cards: cards, index: 0, showingFront: true };
}

function getCounterText(state) {
  if (!state.cards.length) return "";
  return "Card " + (state.index + 1) + " of " + state.cards.length;
}

function getVisibleText(state) {
  if (!state.cards.length) return "";
  const card = state.cards[state.index];
  if (!card) return "";
  return state.showingFront ? card.front : card.back;
}

// Keep this line last. List every function ui.js or the tests use.
if (typeof module !== "undefined") module.exports = { addCard, flipCard, shuffleDeck, getCounterText, getVisibleText, loadData, saveData };

