const test = require("node:test");
const assert = require("node:assert/strict");
const app = require("../app.js");

const empty = { cards: [], index: 0, showingFront: true };

test("addCard rejects empty input and accepts valid input", () => {
  const bad = app.addCard(empty, "Capital of France?", "   ");
  assert.equal(bad.ok, false);
  assert.ok(bad.message.length > 0);
  assert.equal(bad.state, empty);
  const good = app.addCard(empty, " Q ", " A ");
  assert.equal(good.ok, true);
  assert.deepEqual(good.state.cards, [{ front: "Q", back: "A" }]);
  assert.equal(good.state.index, 0);
});

test("flipCard toggles and getVisibleText/getCounterText follow", () => {
  const s = { cards: [{ front: "Q", back: "A" }, { front: "Q2", back: "A2" }], index: 1, showingFront: true };
  assert.equal(app.getVisibleText(s), "Q2");
  const f = app.flipCard(s);
  assert.equal(app.getVisibleText(f), "A2");
  assert.equal(app.getCounterText(f), "Card 2 of 2");
  assert.equal(app.flipCard(empty), empty);
  assert.equal(app.getCounterText(empty), "");
});

test("shuffleDeck keeps the same cards and resets index", () => {
  const cards = [1, 2, 3, 4].map((n) => ({ front: "f" + n, back: "b" + n }));
  const r = app.shuffleDeck({ cards, index: 3, showingFront: false }, () => 0);
  assert.equal(r.index, 0);
  assert.equal(r.showingFront, true);
  assert.equal(r.cards.length, 4);
  assert.deepEqual(r.cards.slice().sort((a, b) => a.front.localeCompare(b.front)), cards);
});

