// Connects the page (index.html) to the logic in app.js.
(function () {
  var $ = function (id) { return document.getElementById(id); };
  var loaded = loadData();
  var state = { cards: Array.isArray(loaded) ? loaded : [], index: 0, showingFront: true };

  function render() {
    var empty = state.cards.length === 0;
    $('card-display').textContent = getVisibleText(state);
    $('counter').textContent = getCounterText(state);
    $('empty-state').hidden = !empty;
    $('card-display').hidden = empty;
    $('counter').hidden = empty;
    $('flip-btn').hidden = empty;
    $('shuffle-btn').hidden = empty;
  }

  $('add-btn').addEventListener('click', function () {
    var r = addCard(state, $('front-input').value, $('back-input').value);
    if (r.ok) {
      state = r.state;
      saveData(state.cards);
      $('front-input').value = '';
      $('back-input').value = '';
      $('message').textContent = '';
    } else {
      $('message').textContent = r.message;
    }
    render();
  });

  $('flip-btn').addEventListener('click', function () {
    state = flipCard(state);
    render();
  });

  $('shuffle-btn').addEventListener('click', function () {
    state = shuffleDeck(state);
    saveData(state.cards);
    render();
  });

  render();
})();
